#!/usr/bin/env bash
# run_hprc_pilot.sh - pilot: tandex on 20 haplotypes (10 people, 10 populations) of HPRC release 2.
# Run in Ubuntu (WSL):   bash /mnt/c/chm13/run_hprc_pilot.sh
# Safe to stop and re-run: finished haplotypes are skipped. Needs ~/tandex/tandex 0.7.2 and about 25 GB on C:.
# Per haplotype: about 3 minutes of download and 15 to 20 minutes of tandex; about 7 hours in all.
set -uo pipefail
TANDEX=${TANDEX:-$HOME/tandex/tandex}
ASM=/mnt/c/chm13/hprc; RES=/mnt/c/chm13/results/hprc
THREADS=${THREADS:-12}
mkdir -p "$ASM" "$RES"
exec > >(tee -a "$RES/run_hprc_pilot.log") 2>&1
echo "=== run_hprc_pilot.sh started $(date) ==="
[ -x "$TANDEX" ] || { echo "ERROR: $TANDEX not found"; exit 1; }
echo "tandex $($TANDEX -v), $THREADS workers"; df -h /mnt/c | tail -1
get() { [ -n "$1" ] || return 0; [ -s "$2" ] || curl -sL --fail --retry 5 --retry-delay 10 -o "$2" "$1" || { echo "  download failed: $1"; rm -f "$2"; return 1; }; }
n=0; done_n=0
while IFS=$'\t' read -r name sample pop sex fa censat cen alias t2t gaps; do
  [ -n "$name" ] || continue
  n=$((n+1)); d=$RES/$name; mkdir -p "$d"
  echo; echo "--- [$n/20] $name ($pop, $sex) ---"
  printf "%s\t%s\t%s\t%s\n" "$name" "$sample" "$pop" "$sex" > "$d/sample.tsv"
  get "$censat" "$d/cenSat.bed"; get "$cen" "$d/active_centromeres.bed"; get "$alias" "$d/chromAlias.txt"
  get "$t2t" "$d/t2t_chromosomes.tsv"; get "$gaps" "$d/gaps.bed"
  if [ -s "$d/tandex.tsv.gz" ]; then echo "already done"; done_n=$((done_n+1)); continue; fi
  f=$ASM/$name.fa.gz
  if [ ! -s "$f" ]; then
    echo "downloading assembly ..."
    curl -L --fail --retry 5 --retry-delay 10 -C - -o "$f.part" "$fa" && mv "$f.part" "$f" || { echo "ASSEMBLY DOWNLOAD FAILED: $name"; continue; }
  fi
  gzip -t "$f" 2> /dev/null || { echo "assembly file is damaged, removing it; re-run the script to fetch it again"; rm -f "$f"; continue; }
  s=$(date +%s)
  "$TANDEX" -p 50000 -t "$THREADS" "$f" > "$d/tandex.tsv.part" || { echo "TANDEX FAILED: $name"; rm -f "$d/tandex.tsv.part"; continue; }
  echo "TIME $name $(( $(date +%s) - s )) s; calls: $(grep -vc '^#' "$d/tandex.tsv.part")"
  gzip -f "$d/tandex.tsv.part" && mv "$d/tandex.tsv.part.gz" "$d/tandex.tsv.gz" && done_n=$((done_n+1))
done <<'LIST'
